function M.command(d,s)
    if not d or d.room~=s.room or not M.id(d.actor) then return nil end
    if d.channel==4 then
        if s.leader~=s.self_id then return nil end
        if d.kind=="team_cover" and M.id(d.protected) and s.members[d.protected] then
            return "rozkaz druzynie zaslonic "..(d.protected==s.self_id and "ciebie" or d.protected)
        end
        if d.kind=="team_attack" and M.id(d.enemy) and s.enemies[d.enemy] then return "rozkaz druzynie zaatakowac "..d.enemy end
        if d.kind=="cover" and M.id(d.protected) and s.members[d.protected] and M.id(d.enemy)
            and s.leader==s.self_id and s.members[d.actor] and s.members[d.actor].kind=="player" then
            if d.protected~=s.self_id then return "rozkaz "..d.actor.." zaslonic "..d.protected end
            return "rozkaz "..d.actor.." zaslonic ciebie przed "..d.enemy
        end
        return nil
    elseif d.channel==1 then
        if not M.id(d.protected) then return nil end
        if d.kind=="retreat" then return "wycofaj sie za "..d.protected end
        if d.kind=="mass" then return "zaslon "..d.protected end
        if d.kind=="cover" and M.id(d.enemy) then return "zaslon "..d.protected.." przed "..d.enemy end
    else
        local prefix="parozkaz "..d.actor.." "
        if d.kind=="support" and M.id(d.enemy) then return prefix.."wesprzyj" end
        if d.kind=="cover" and M.id(d.enemy) and M.id(d.protected) then
            return prefix.."zaslon "..d.protected.." przed "..d.enemy
        end
    end
end
function M.confirmed(d,s)
    if s.room~=d.room then return false end
    if d.kind=="team_attack" then
        for _,id in ipairs(d.recipients) do if s.targets[id]~=d.enemy then return false end end
        return true
    end
    if d.kind=="team_cover" then
        for _,enemy in ipairs(d.before_targets) do
            for _,id in ipairs(d.recipients) do if s.targets[enemy]==id then return true end end
        end
        return false
    end
    if d.kind=="support" then return s.targets[d.actor]==d.enemy end
    if d.kind=="cover" and not d.broad then return s.targets[d.enemy]==d.actor end
    local target=d.kind=="retreat" and d.protected or d.actor
    for _,enemy in ipairs(d.before_targets or {}) do if s.targets[enemy]==target then return true end end
    return false
end
return M
end
factories["integration"] = function()
-- Read-only compatibility boundary for official Chimera 5 and older addons.
-- No global send interception and no silent changes to the player's settings.
local I={}
function I.new(ctx)
    local function old_automation()
        for _,name in ipairs({"tacticus","tactician","tacticus_ng"}) do
            local old=rawget(_G,name)
            if type(old)=="table" then
                if old.mode=="auto" or (type(old.state)=="table" and old.state.on) then
                    return "Wyłącz poprzedni Tacticus przed uruchomieniem ChimeraXP."
                end
            end
        end
    end
    local function setting(module,key)
        local config=ctx.app and ctx.app.config
        if config and type(config.get)=="function" then
            local ok,value=pcall(config.get,config,module,key)
            if not ok then return nil,"Nie można sprawdzić ustawień: "..module end
            return value
        end
    end
    local function status(name,method)
        local records=ctx.app and ctx.app.loader and ctx.app.loader.records
        local record=records and records[name]
        if record and record.status=="running" and record.api and type(record.api[method])=="function" then
            local ok,value=pcall(record.api[method])
            if not ok then return nil,"Nie można sprawdzić modułu "..name end
            return value
        end
    end
    return {
        check=function(patrol)
            local reason=old_automation();if reason then return reason end
            local bot,err=status("bots","status")
            if err then return err end
            if bot then return "Działa oficjalny bot. Zatrzymaj go przed automatyką ChimeraXP." end
            local chase,why=setting("team","autopogon")
            if why then return why end
            if patrol and chase then return "Wyłącz /autopogon przed patrolem ChimeraXP." end
            local support,e=setting("team","autowsparcie")
            if e then return e end
            if support then return "Wyłącz /autowsparcie: celami ma sterować jeden automat." end
            if patrol then
                local hooks,problem=status("automation","summary")
                if problem then return problem end
                if type(hooks)=="table" and #hooks>0 then
                    return "Aktywne /pre_walk, /post_walk lub /post_fight. Wyłącz je przed patrolem."
                end
                local collect,err2=setting("collect","zbieranie")
                if err2 then return err2 end
                if collect and patrol.economy and patrol.economy.enabled and #(patrol.loot or {})>0 then
                    return "Wyłącz oficjalne /zbieranie: łupy tego profilu obsługuje ChimeraXP."
                end
            end
        end,
        migrate_tactics=function()
            local storage=ctx.app and ctx.app.storage
            if storage and type(storage.get_state)=="function" then
                local ok,config=pcall(storage.get_state,storage,"tacticus_ng","config")
                if ok and type(config)=="table" then return config end
            end
        end,
    }
end
return I
end
factories["tactics"] = function()
-- One in-flight maneuver. Every plan is re-evaluated against current GMCP.
local T={}
function T.new(ctx,M,integration,patrol,changed)
